int dccp_v4_do_ioctl(struct sock *sk, struct sk_buff *skb,
                     struct dccp_hdr *dh, unsigned int len)
{
    int err = 0;

    switch (sk->sk_state) {
    case DCCP_LISTEN:
        if (dh->dccph_type != DCCP_PKT_REQUEST) {
            err = 1;
            break;
        }
        /* Process connection request */
        if (!dccp_validate_options(skb, dh)) {
            err = 1;
            break;
        }
        sk->sk_state = DCCP_RESPOND;
        break;

    case DCCP_CLOSED:
        err = 1;
        break;

    case DCCP_REQUESTING:
        if (dh->dccph_type == DCCP_PKT_RESET) {
            dccp_send_reset(sk, skb);
            sk->sk_state = DCCP_CLOSED;
            err = 0;
            break;
        }
        if (dh->dccph_type != DCCP_PKT_RESPONSE) {
            err = 1;
            break;
        }
        /* Validate response and proceed to open state */
        if (!dccp_validate_options(skb, dh)) {
            err = 1;
            break;
        }
        sk->sk_state = DCCP_OPEN;
        break;

    case DCCP_PARTOPEN:
    case DCCP_RESPOND:
        if (dh->dccph_type == DCCP_PKT_RESET) {
            dccp_send_reset(sk, skb);
            sk->sk_state = DCCP_CLOSED;
            err = 0;
            break;
        }
        if (dh->dccph_type != DCCP_PKT_ACK && dh->dccph_type != DCCP_PKT_SYNC) {
            err = 1;
            break;
        }
        dccp_process_ack_sync(sk, dh);
        break;

    default:
        err = 1;
        break;
    }

    if (err)
        kfree_skb(skb);

    return err;
}

int dccp_process_packet(struct sock *sk, struct sk_buff *skb, struct dccp_hdr *dh, unsigned int len)
{
    if (sk == NULL || skb == NULL || dh == NULL) {
        return 1;
    }

    switch (sk->sk_state) {
        case TCP_ESTABLISHED:
        case TCP_LISTEN:
        case DCCP_REQUESTING:
        case DCCP_PARTOPEN:
        case DCCP_RESPOND: {
            if (len < sizeof(*dh)) {
                return 1;
            }

            if (dh->dccph_type == DCCP_PKT_RESET) {
                dccp_disconnect(sk, 0);
                return 0;
            }

            if (dh->dccph_type != DCCP_PKT_DATA &&
                dh->dccph_type != DCCP_PKT_ACK &&
                dh->dccph_type != DCCP_PKT_SYNC &&
                dh->dccph_type != DCCP_PKT_SYNCACK) {
                return 1;
            }

            switch (dh->dccph_type) {
                case DCCP_PKT_ACK:
                    dccp_handle_ack(sk, dh, len);
                    break;
                case DCCP_PKT_SYNC:
                    dccp_handle_sync(sk, dh, len);
                    break;
                default:
                    if (!dccp_process_options(sk, skb, dh, len)) {
                        return 1;
                    }
            }
        }
        break;
        default:
            return 1;
    }

    return 0;
}

int dccp_process_incoming_packet(struct sock *sk, struct sk_buff *skb,
                                 struct dccp_hdr *dh, unsigned int len)
{
    int ret = 0;

    switch (sk->sk_state) {
    case TCP_LISTEN:
        if (dh->dccph_type == DCCP_PKT_REQUEST && len >= sizeof(struct dccp_hdr)) {
            dccp_handle_request(sk, skb, dh);
            ret = 0;
        } else {
            ret = 1;
        }
        break;

    case TCP_CLOSE:
        ret = 1;
        break;

    case DCCP_REQUESTING:
        if (dh->dccph_type == DCCP_PKT_RESPONSE && len >= sizeof(struct dccp_hdr)) {
            dccp_handle_response(sk, skb, dh);
            ret = 0;
        } else {
            ret = 1;
        }
        break;

    case DCCP_PARTOPEN:
        if (dh->dccph_type == DCCP_PKT_DATA || dh->dccph_type == DCCP_PKT_ACK) {
            dccp_handle_data_or_ack(sk, skb, dh, len);
            ret = 0;
        } else if (dh->dccph_type == DCCP_PKT_RESET) {
            dccp_teardown_connection(sk, skb, dh);
            ret = 0;
        } else {
            ret = 1;
        }
        break;

    case DCCP_RESPOND:
        if (dh->dccph_type == DCCP_PKT_DATAACK) {
            dccp_handle_dataack(sk, skb, dh, len);
            ret = 0;
        } else if (dh->dccph_type == DCCP_PKT_RESET) {
            dccp_teardown_connection(sk, skb, dh);
            ret = 0;
        } else {
            ret = 1;
        }
        break;

    default:
        ret = 1;
        break;
    }

    return ret;
}

int dccp_process_packet(struct sock *sk, struct sk_buff *skb, struct dccp_hdr *dh, unsigned int len)
{
    switch (sk->sk_state) {
    case TCP_LISTEN:
        if (dh->dccph_type != DCCP_PKT_REQUEST)
            return 1;
        if (!dccp_validate_options(skb, dh))
            return 1;
        dccp_send_response(sk, skb);
        break;
    case TCP_CLOSE:
        return 1;
    case DCCP_REQUESTING:
        if (dh->dccph_type == DCCP_PKT_RESET) {
            dccp_terminate_connection(sk);
            return 0;
        }
        if (dh->dccph_type != DCCP_PKT_ACK)
            return 1;
        break;
    case DCCP_PARTOPEN:
    case DCCP_RESPOND:
        if (dh->dccph_type == DCCP_PKT_RESET) {
            dccp_terminate_connection(sk);
            return 0;
        }
        if (dh->dccph_type == DCCP_PKT_ACK)
            dccp_handle_ack(sk, dh);
        else if (dh->dccph_type == DCCP_PKT_SYNC)
            dccp_handle_sync(sk, dh);
        else
            return 1;
        break;
    default:
        return 1;
    }

    if (!dccp_validate_packet(skb, dh, len))
        return 1;

    dccp_update_state(sk, dh);
    return 0;
}

int dccp_process_packet(struct sock *sk, struct sk_buff *skb, struct dccp_hdr *dh, unsigned int len)
{
    if (!skb || !dh)
        return 1;

    switch (sk->sk_state) {
        case DCCP_LISTEN:
            if (dh->dccph_type != DCCP_PKT_REQUEST)
                return 1;
            if (dccp_handle_request(sk, skb, dh, len) != 0)
                return 1;
            break;
        case DCCP_CLOSED:
            return 1;
        case DCCP_REQUESTING:
            if (dh->dccph_type != DCCP_PKT_DATAACK && dh->dccph_type != DCCP_PKT_RESET)
                return 1;
            if (dccp_handle_dataack(sk, skb, dh, len) != 0)
                return 1;
            break;
        case DCCP_PARTOPEN:
        case DCCP_RESPOND:
            if (dh->dccph_type == DCCP_PKT_RESET) {
                dccp_send_reset(sk, skb, dh);
                return 1;
            }
            if (dccp_validate_options(sk, dh, len) != 0)
                return 1;
            if (dh->dccph_type == DCCP_PKT_ACK) {
                if (dccp_process_ack(sk, dh, len) != 0)
                    return 1;
            } else if (dh->dccph_type == DCCP_PKT_SYNC) {
                if (dccp_process_sync(sk, dh, len) != 0)
                    return 1;
            } else if (dh->dccph_type == DCCP_PKT_DATA) {
                if (dccp_process_data(sk, skb, dh, len) != 0)
                    return 1;
            } else {
                return 1;
            }
            break;
        default:
            return 1;
    }

    return 0;
}
